import gzip,glob
for f in sorted(glob.glob('studies/data/raw/*series_matrix*')):
    print('=====',f)
    for l in gzip.open(f,'rt',errors='replace'):
        if l.startswith('!series_matrix_table_begin'): break
        if l.startswith('!Sample_title') or l.startswith('!Sample_geo') or l.startswith('!Sample_characteristics') or l.startswith('!Sample_source') or l.startswith('!Sample_description'):
            print(l[:3000].rstrip())

